      summary: "2026-10-30複核：依自由時報具名報導，蔡煌瑯於2016-01-06赴南投地檢署，對時任中國國民黨南投縣黨部主委李哲華提出加重誹謗及違反選罷法告訴；這只證明歷史上曾提出告訴，目前刑事程序未知。李哲華否認抹黑，主張看板及文宣附有高檢署上訴文號、內容有所本；此為本人說法，不是檢方或法院認定。就同一看板爭議，蔡煌瑯對李哲華等人的民事損害賠償請求，南投地院105年度訴字第4號於2016-05-04駁回，臺中高分院105年度上字第311號於2016-11-01再駁回上訴；這是民事有利結果，不等於刑事不起訴、無罪或告訴已結案。本次未取得刑事案號、偵結、撤回、起訴或刑事裁判資料，不表示目前仍在偵查，更不是犯罪、有罪或案底認定。使用者依此窄幅歷史提告紀錄補充本人個人避開。原名冊理由與時點限制：使用者依2026-06-26既有中國國民黨黨中央公開黨職名冊，對李哲華本人個人避開；只記錄該日公開角色，不保證今日仍在任或黨籍未變，也不推定政黨或其他關係人責任。",
