      aiNotes: "原名冊及拆卡沿用2026-06-26公開角色與來源日期，未據歷史報導推定2026-10-30即時黨職或黨籍；政黨分類只依該既有來源時點，不表示案發時黨籍或政黨責任。2026-10-30僅補獨立source review核准的lee-tsai-billboard-2015-16：可確認的範圍只有2016-01-06蔡煌瑯已對李哲華提出加重誹謗及違反選罷法告訴，罪名是告訴方主張，不是檢方或法院認定。保留李哲華否認抹黑及主張文宣有所本，也必須保留同一看板民事損害賠償一審、二審請求均遭駁回的有利脈絡；民事駁回不是刑事不起訴、無罪或告訴結案。本次未取得刑事案號、偵結、撤回、起訴或刑事裁判，目前程序unknown；不得寫現在仍偵查、已起訴、審理、犯罪、有罪、定讞或案底，未取得也不等於不存在後續。民事二審未取得確定日期或後續最高法院文書，不稱確定。看板內容所涉350萬元及8年刑度是蔡煌瑯另案，不得移植為李哲華的收賄、犯罪所得或刑度。只適用李哲華本人，不把中國國民黨南投縣委員會、蔡煌瑯、其他同名者、證人或其他案件責任移入本卡；同名命中維持未確認同人，也未證明不是本人。原研究coverage_status為blocked，表示刑事後續仍有精確缺口，不是完整前科證明或沒有其他案件；司法院姓名索引可能漏列遮名裁判或未公開偵查。維持personal／high；high只指既有名冊身分及具名媒體與兩份官方民事裁判支持上述窄幅事實，不是指控成立、犯罪機率、目前程序或整人研究完備度。name／aliases／identifiers維持原值，姓名鍵不納加重誹謗、選罷法、蔡煌瑯、看板、case key或其他事件詞。司法分類只供歷史司法程序導覽，不表示有罪或現行案件。source report SHA-256：361ee6600acd7cae502fa981990f1320b415361817629a9d05c1ad89ea5a72ac；source review SHA-256：47113a3064bc7d22860bb8c7237cda2c6b20d16b44f69395c73a26ff8d9d4fb4。",
