      summary: "2026-10-31複核：張雅屏的2014年屏東縣長及縣議員選舉不實文宣刑案已確認有罪定讞。最高法院106年度台上字第1509號於2017-05-18駁回其上訴；高雄高分院107年度聲字第1378號後續記載最高法院駁回確定後移送執行。原判依公職人員選舉罷免法第104條散布謠言接續犯一罪，與修正前個人資料保護法第41條之罪想像競合，從一重處有期徒刑2年10月、褫奪公權5年。附件一文宣部分未能證明違反選罷法第104條，但不另為無罪諭知，不能把全部文宣都寫成有罪。張雅屏聲請非常上訴遭最高檢察署駁回、聲請解釋遭司法院不受理，兩者都不是撤銷原判或改判無罪。107聲1378另載法務部於2018-11-19核准假釋，法院於2018-11-20裁定假釋中付保護管束；這些只是歷史執行後續，不表示2026年仍在服刑、假釋、保護管束或褫奪公權。相關民事責任另行標示：最高法院109年度台上字第1669號於2021-02-25駁回林郁虹案上訴，中央社具名報導載中國國民黨與張雅屏連帶給付新臺幣60萬元非財產上損害賠償（精神慰撫金）並登報道歉；這是民事責任，不是刑事罰金、犯罪所得或訴訟費用。最高法院109年度台上字第1203號於2021-01-20駁回潘孟安案上訴，自由時報具名報導載二審已將登報道歉由5日減為2日。本次未取得刑事判決的精確確定日期，也未作完整前科清查；司法院姓名索引及有限後續搜尋可能漏列遮名裁判或未公開偵查，同名而未有身分橋接者不歸入本人。原名冊理由與時點限制：使用者依2026-06-26既有中國國民黨黨中央公開黨職名冊，對張雅屏本人個人避開；只記錄該日公開角色，不保證今日仍在任或黨籍未變，也不推定政黨或其他關係人責任。",
