      aiNotes: "原名冊及拆卡沿用2026-06-26公開角色與來源日期；政黨分類只依該既有來源時點，不表示2026-10-31即時黨職、案發時黨籍或政黨責任。2026-10-31只補獨立source review核准的chang-yaping-election-defamation-2014，並在同一人物紀錄保留兩件同一2014文宣事件的確定民事責任脈絡；不另建chang-yaping-lin-yuhung-civil或chang-yaping-pan-mengan-civil重複人物卡。刑事可確認範圍為最高法院106年度台上字第1509號於2017-05-18駁回上訴，原判依選罷法第104條散布謠言接續犯一罪，與修正前個資法第41條之罪想像競合而從一重處有期徒刑2年10月、褫奪公權5年；附件一文宣部分不能證明而不另為無罪諭知，不能擴成全部文宣均有罪。高雄高分院107年度聲字第1378號記載最高法院駁回確定後移送執行，足以確認有罪定讞，但本次未取得判決確定證明或精確確定日期，不以2017-05-18裁判日、2017年6月底非常上訴聲請駁回日、2018-11-19假釋核准日或2018-11-20保護管束裁定日代替。聲請非常上訴遭最高檢察署駁回、聲請解釋遭司法院不受理，均不是撤銷原判、改判無罪或再審結果。2018年假釋及付保護管束只是歷史執行後續，不推定2026仍在服刑、假釋、保護管束或褫奪公權。林郁虹案60萬元是民事非財產上損害賠償／精神慰撫金並有登報道歉，不是刑事罰金、犯罪所得或訴訟費用；潘孟安案是二審將登報道歉由5日減為2日，兩案不得混算，也不推定2026仍負尚未履行義務。只適用張雅屏本人；46筆司法院姓名全文索引中的臺中社區主委、證券帳戶名義人、民事債權人／債務人、被害人／告訴人、證人或法人代表等同名命中沒有身分橋接，維持未確認同人，也未證明不是本人，不移入本卡。原研究coverage_status為complete只代表既定公開查詢範圍完成；姓名索引可能漏列遮名裁判或未公開偵查，有限後續反查也不是完整前科證明，不能宣稱沒有其他案件。維持personal／high；high只指既有名冊身分與官方裁判、具名報導支持上述窄幅事實，不是刑期現況、整人研究完備度或政黨責任。name／aliases／identifiers維持原值，姓名鍵不納罪名、案號、case key、林郁虹、潘孟安、政黨、黨職或其他事件詞；司法分類只供相關司法結果導覽。source report SHA-256：f0afe28677c907e97893df8476fe772ef19c466e342a0e999d1fde64d3770363；source review SHA-256：623443b8d802be2395f2a3084f9cfc67ee14a7690589df6c9b59682f75fd82da。必要節錄SHA-256：國民黨身分64d849438f3dc9cb3ad3b17e96cac0071a43a662bb227dcf30f92ff906581e66、刑事判決30f21bb6f07da334223537a2433c683e89776e4c37fbca1b6cc41cd8e6e1205f、非常上訴db4db2d8323eedab7a5ba228d98ac8c17e16beba45ed11df9d1ea73374ed977d、假釋／定讞3f6cb09c346e511017433365ef4969026a4cf69996c61863ae4616e05d062d95、林郁虹官方6a0b7f2b31a7e1a6fd630dee909d541ca37deac5f4141091e6f095958ba43801、林郁虹報導f6bf68ebad9e290c524d519ffbf8b23e9f236c024a3fd973b7e56f61ba291a86、潘孟安官方ae3e42bc3b157072f60a6aa63dd564d73302a0462633d3b1a388e103d67b29cc、潘孟安報導0d9bd18a56bb32f503378abe24d235b98b7290a542d644bad5895316f41ec41f、46筆姓名索引dfbecb1d0953632f51ff2e26370614c83b1498d62fb4fae435bb62960e2b21ac、聲請解釋不受理b46506bb95ec85f356480699e58d76b244a02ff6527d435fded8e0130076cedf。",
