      summary: "2026-10-31複核。案件一｜2004西螺交通事故：臺灣雲林地方法院94年度交易字第161號於2006-10-11認定匿名被告丁○○駕駛自小客車行經閃光紅燈路口時未先停車再開，與超速行經閃光黃燈路口的重機碰撞，致後座乘客白啟鴻死亡；法院依修正前刑法過失致死罪判有期徒刑6月、得易科罰金、緩刑2年，並記載已與家屬和解。官方裁判的事故日期、地點、死者、證人李佳芬及刑度，與鏡週刊、公視具名正文所載韓國瑜的同一事故相符，完成匿名裁判身分橋接。司法院頁面雖顯示本件無歷審裁判，判決仍附上訴教示；本次未取得正式確定證明、精確確定日期或執行資料，因此只寫一審有罪裁判、確定性未確認，不寫定讞、實際易科罰金或已執行完畢，也不改寫成酒駕、肇逃、故意殺人或全部肇責。94年度交易字第14號是同事故重機駕駛另案，只用於防止案號混淆。案件二｜2018雞排助選告發：高雄市選舉委員會第84次會議紀錄載，民眾檢舉朱學恒以雞排變相助選、涉嫌期約賄選，並指韓國瑜為共犯；選委會同時明示犯罪及當選無效屬司法機關認定範疇、本會無偵查權，決議函請高雄地檢署自行審酌。這只證明2018-12-18有官方紀錄的歷史告發，不是選委會、檢方或法院認定犯罪；本次未取得可歸屬此告發的檢方分案案號、偵結、起訴或裁判，目前程序未知，不表示仍在偵查、已起訴、有罪、定讞或有案底。雞排份數或報稱金額也不表示韓國瑜收受、交付、約定或取得犯罪所得。原名冊理由與時點限制：使用者依2026-06-26既有中國國民黨第十一屆立法委員／黨團名冊，對韓國瑜本人個人避開；政黨分類只依該既有來源時點，不保證2026-10-31即時黨籍或職務，也不倒填2004年案發時黨籍或推定政黨責任。",
      sources: [
        kmtPublicFigureSources[1],
        kmtPublicFigureSources[2],
        source("臺灣雲林地方法院94年度交易字第161號刑事判決", "https://judgment.judicial.gov.tw/LAW_Mobile_FJUD/FJUD/data.aspx?ty=JD&id=ULDM%2C94%2C%E4%BA%A4%E6%98%93%2C161%2C20061011%2C1", "2006-10-11", "司法院官方一審判決支持匿名被告丁○○、2004-01-03西螺事故、死者白啟鴻、證人李佳芬、修正前刑法過失致死、有期徒刑6月、得易科罰金、緩刑2年、已與家屬和解、裁判日及頁面所示本件無歷審裁判；公開裁判匿名且附上訴教示，不直接支持韓國瑜全名、正式確定證明、精確確定日期、實際易科罰金或執行情形。source-review必要節錄SHA-256：6388dbc846739611453d7e6c3b83977f12c69b68685098b27fdf8ee0cebd2f03，非完整裁判全文雜湊。"),
        source("韓國瑜曾撞死人和解 無前科緩刑2年", "https://www.mirrormedia.mg/story/amp/20181129inv001", "2018-11-29", "鏡週刊林俊宏具名正文支持全名韓國瑜與相同事故日期、地點、型態、6月刑度、緩刑2年及和解的身分橋接；裁判案號與日期以司法院94年度交易字第161號、2006-10-11為準。媒體標題的「無前科」不作韓國瑜全人或完整司法紀錄結論，本來源也不是判決確定或執行證明。必要節錄SHA-256：6094c74ff7be09f2acd568c2751c59c07753057b47dabd89dd95375e7655d72c，非完整HTML雜湊。"),
        source("曾駕車撞重機致死 韓國瑜坦承已受罰", "https://news.pts.org.tw/article/414542", "2018-11-29", "公視王柔婷、陳顯坤具名正文支持韓國瑜與2004西螺雙載重機事故、白姓後座乘客死亡、6月、得易科罰金及緩刑2年的第二份獨立身分橋接；不是正式確定證明，也不因標題或報導用語推定已實際易科罰金、執行完畢或其他未取得程序。必要節錄SHA-256：307d0a4cbd573a2014f98658bae1ecf134ebb9a05b1b8b9f9eb5bd818acda6e1，非完整HTML雜湊。"),
        source("臺灣雲林地方法院94年度交易字第14號刑事判決", "https://judgment.judicial.gov.tw/LAW_Mobile_FJUD/FJUD/data.aspx?ty=JD&id=ULDM%2C94%2C%E4%BA%A4%E6%98%93%2C14%2C20050829%2C1", "2005-08-29", "司法院官方判決支持第14號被告丙○○是同事故重機駕駛，丁○○才是自小客車駕駛；本來源只用於隔離另案、防止把第14號誤寫成韓國瑜案，不增加韓國瑜的罪名、刑度或責任。source-review必要節錄SHA-256：f6fc4caa6bdd24559d473ed0585fb6e315404ad2623ec5175ce54054bc99539c，非完整裁判全文雜湊。"),
        source("高雄市選舉委員會第84次委員會議紀錄", "https://web.cec.gov.tw/api/file/e968f084-ac34-4455-bcba-291284eee385.pdf", "2018-12-18", "高雄市選舉委員會官方會議紀錄第3案支持檢舉人指述朱學恒以雞排變相助選、涉嫌期約賄選並指韓國瑜為共犯，也支持選委會明示犯罪及當選無效屬司法認定、本會無偵查權，決議函請高雄地檢署自行審酌。期約賄選與共犯是檢舉人主張，不是選委會、檢方或法院實體認定；本來源不支持檢方分案、偵結、起訴、有罪、定讞、目前仍偵查，或韓國瑜收受、交付、約定雞排與金額及取得犯罪所得。官方PDF SHA-256：4c1a3cf3f92782745749d9677b25f7ae8e1eba8dceca1074509aaff2b781f824。"),
      ],
      aiNotes: "原名冊及拆卡沿用2026-06-26公開角色、兩項既有名冊來源與來源日期；政黨分類只依該時點，不表示2026-10-31即時黨籍或職務、2004案發時黨籍或政黨責任。2026-10-31只補獨立source review核准且必須同卡完整可見的兩案：han-2004-traffic與han-chicken-election-complaint-2018。交通案可確認臺灣雲林地方法院94年度交易字第161號於2006-10-11作成過失致死一審有罪裁判，判有期徒刑6月、得易科罰金、緩刑2年並記載已和解；匿名身分由事故日期地點、死者白啟鴻、證人李佳芬及刑度，與鏡週刊、公視具名正文交叉橋接韓國瑜。頁面所示本件無歷審裁判不能取代正式確定證明，且判決附上訴教示；未取得正式確定證明、精確確定日期或執行資料，故確定性未確認，不寫定讞、實際易科罰金、已執行完畢、酒駕、肇逃、故意殺人或全部肇責。第14號是同事故重機駕駛另案，只作防混淆。雞排案只可確認2018-12-18高雄市選委會官方會議紀錄所載歷史告發及函請高雄地檢署自行審酌；期約賄選與共犯是檢舉人指述，選委會明示無偵查權且未自行認定犯罪。本次未取得檢方分案案號、偵結、起訴、當選無效訴訟或刑事裁判，目前程序unknown；不得寫仍偵查、犯罪成立、起訴、有罪、定讞、案底、不起訴或無罪，也不得把雞排份數或金額移作韓國瑜收受、交付、約定或犯罪所得。source review排除han-northfarm-3-nonprosecution、han-foreign-2019、han-sanlih-defamation-nonprosecution-2020、han-319-defamation-nonprosecution-2021：北農、訪港、三立及319已有不起訴或查無不法簽結的有利後續，不轉成負面案件；另排除han-recall-stay-109停27與han-recall-stay-109停41，因本人是行政聲請人／抗告人，抗告駁回不是刑事定罪。2020振興購物嘉年華報導的告發對象是高雄市政府，也不倒置為本人。同名命中、姓名索引及公開搜尋均可能漏列遮名裁判或未公開偵查，不是完整前科證明；不能宣稱沒有其他案件或以鏡週刊標題「無前科」作全人結論。維持personal／high；high只指既有名冊身分及核准來源支持上述窄幅事實，不是犯罪機率、確定性、目前程序或整人研究完備度。name／aliases／identifiers維持原值，搜尋鍵不納案件、罪名、案號、朱學恒、雞排、選罷法、李佳芬、政黨、黨職、case key或其他事件詞；司法分類只供相關司法紀錄導覽。source report SHA-256：4015b5d1f436360ee471cce358f7cd691aaa349ad4cc8fc0f51d7c687ac8726a；source review SHA-256：e6fc521b273e88ea6db1ccdf5af2ae1831b644a35db922fa0f97c996960cc16f。",
