      summary: "2026-10-31複核。唯一核准案件｜2025-10-08歷史刑事告訴（目前程序未知）：中央社兩篇具名正文及自由時報現場報導記載，民進黨立委賴瑞隆於2025-10-08委由律師前往高雄地方檢察署，針對前一日美濃大峽谷相關記者會言論，至少對國民黨立委柯志恩提出加重誹謗告訴。賴方主張柯志恩及國民黨高雄市議會黨團將涉盜採砂石地主的家屬與其團隊連結；這是賴方的告訴內容，不是檢方或法院認定。柯志恩回應，她在記者會只談修法及遏止盜採，從頭到尾沒有說出賴瑞隆姓名，並批評對方濫用司法資源；這是柯方說法，不是司法認定。本次查核截至2026-10-31未取得可歸屬此告訴的檢方案號、起訴、不起訴、撤回、再議或法院裁判，因此只證明2025-10-08歷史上確曾提告，目前程序未知，不表示柯志恩犯罪、已起訴、有罪、定讞、有案底、仍在偵查、已不起訴、無罪或案件已終結，也不表示司法機關認定柯志恩參與盜採砂石。不同人的有利邊界：許采蓁於2026-09-14向聯合報表示，自己因相關但不同的地主關係言論遭賴瑞隆提告後獲不起訴；本次未取得官方處分書，且被告訴人與具體言論不同，不能作為柯志恩案件的偵結結果，也不能推論兩人屬同一處分或同一事實範圍。原名冊理由與時點限制：使用者依2026-06-26既有中國國民黨第十一屆立法委員／黨團名冊，對柯志恩本人個人避開；立法院官方頁於2026-10-31查取時列Ko, Chih-En為第11屆KMT全國不分區立委，中國國民黨官方人物頁亦列柯志恩為全國不分區立委。政黨分類只依這些明示來源時點，不保證未來黨籍或職務，也不倒推案發時全部身分或政黨責任。",
