      aiNotes: "原名冊及拆卡沿用2026-06-26公開角色、兩項既有名冊來源與來源日期；本輪只補獨立source review唯一核准case key chen-vaccine-data-criminal，不另建人物卡、不改群組共用值，也不把chen-vaccine-data-civil當第二個負面事件。可確認範圍為臺北地院111年度訴字第1318號一審判共同犯個人資料保護法第41條非法利用個人資料罪、有期徒刑5月、如易科罰金每日新臺幣1,000元，臺灣高院113年度上訴字第5803號於2025-08-21駁回上訴並宣告緩刑2年；陳菁徽上訴後坦認犯行、與告訴人調解且履行完畢、告訴代理人願給緩刑，均須與二審有罪同時可見。二審仍附上訴教示，2026-11-01歷審頁未列最高法院裁判或紅色最高法院繫屬標記，但這不足單獨證明未上訴或確定；未取得最高法院裁判、判決確定證明或執行文件，故只寫二審有罪、定讞未確認，不把緩刑當無罪，也不作有罪定讞、案底、前科、未上訴、緩刑確定或已執行等結論。民事求償與刑案源於同一行為；刑事二審可證調解且履行完畢，2025-09-18兩篇具名法庭報導只證當日尚未補撤回書狀，未取得正式撤回、裁判或其他終結文件，故2026-11-01現況unknown，不寫民事已撤回、已結案或目前仍在審。案發於2021年，當時裁判可證為禾馨醫療集團醫師；立法院官方頁載2024-02-01才就任第11屆立委，且2021黨籍未確認，不得寫立委任內或以立委身分犯案，也不倒推案發時黨籍。排除他人及反向角色：侯君穎的無罪、撤回告訴／不另為不受理與其確定性不得移植；另名陳姓女子和解撤告後不起訴不是陳菁徽；鍾佳濱案中陳菁徽是自訴／提告方。公開裁判、歷審頁與具名媒體不是完整前科、執行、未公開偵查或所有民事卷證資料庫，不能宣稱已排除所有後續或其他案件。維持personal／high；personal是使用者個人避開，不是司法程序，high只指原名冊身分及核准來源支持上述窄幅事實，不是犯罪機率、有罪定讞、確定性或研究完備度。name／aliases／identifiers維持原值，搜尋鍵不納case key、罪名、案號、林秉樞、疫苗、媒體、法院、中國國民黨、政黨、職稱或其他事件詞；司法分類只供相關紀錄導覽。source report SHA-256：2ac0a3c6594e47ec7b62753eec78dbf1e1be8ca838c871eec6d91fc3c55b21ab；source review SHA-256：1e309be79286ab5ee9270ad0c8631e0818993e2b97c94206f8d4f5aa6bdb3a62；independent worker report SHA-256：cbef606d069b0fff33d26c2ee1239b86e5634f447a4c3e06432f6e50707c8723。",
      lastReviewed: "2026-11-01",
