      aiNotes: "原名冊及拆卡沿用2026-06-26公開角色、兩項既有名冊來源與來源日期；本輪只補獨立source review核准的唯一publish case key hsu-wu-recall-forgery，不新增人物卡、不改群組共用值。hsu-chen-recall-merged必須完整併入同一卡，作陳瑩罷免提議書案於2026-02-12由北檢據報移送屏東地院併辦的組件；檢方稱與伍麗華案有實質上一罪關係，但未取得屏東地院接受併辦裁定全文，故不另建第二案、不雙重計數，也不寫法院已確認正式併案。程序必須分開：2025-10-31屏檢起訴；2026-02-09準備程序；2026-02-12北檢據中央社報導移送併辦；2026-10-13屏東地院115年度聲字第948號理由記載114年度原選訴字第1號現由本院審理中。該聲字裁定主文只處理第三人扣押物，不是許宇甄的實體有利或不利裁判。最新取得的官方狀態證據日期是2026-10-13；2026-11-01只是查取日，未取得其後公開實體裁判，不能把查取日寫成法院狀態日，也不能宣稱法律上必然仍在審或不存在更新。檢方指控只可歸屬為檢方主張：利用原住民黨員名冊分工抄寫罷免提議人名冊，涉偽造文書、個人資料保護法及公職人員選舉罷免法等罪；不得寫法院已認定、有罪、前科、判刑或定讞。許宇甄於2026-02-09否認犯罪、知情及指示抄寫，辯方對對話紀錄完整性、部分偵查供述證據能力與檢方實質舉證責任的爭議必須可見。不得移植同案其他6人認罪、其他人緩起訴、不起訴、死亡、供述或刑度；第三人扣押物發還也不是本人有利結果。未取得屏檢起訴書全文、北檢併辦意旨書全文及屏東地院接受併辦裁定全文；本輪另未取得屏檢起訴新聞稿全文，故來源／程序缺口必須保留。立法院官方頁只依查取時點支持第11屆中國國民黨全國不分區立委、2024-02-01到職及經歷列中央組發會主委；事件時角色由起訴、庭訊與併辦報導橋接為中央組發會主委及不分區立委。政黨分類只依來源明示時點，不保證即時黨籍／未來職務、也不是政黨責任。維持personal／high；personal表示使用者個人避雷，審理中不等於有罪，high只指原名冊身分與核准來源支持上述窄幅事實，不是犯罪機率、有罪確定性或研究完備度。name／aliases／identifiers維持純姓名原值，不納案號、case key、罪名、伍麗華、陳瑩、政黨、職稱、機關、媒體或事件詞。公開搜尋不是完整前科、全部告訴告發、未公開偵查或所有裁判資料庫，不能宣稱沒有其他案件、沒有前科或證明清白。source report SHA-256：4ea21604ae0d3c0aefe4f2f186c60c0dced06bb802f5a0e9be439e67c7b8b703；source review SHA-256：86eda04a77c36b4be2f3d5d3a4af1ccdc494d79bf8a46911c4b1cfc8604d2518；independent worker report SHA-256：2f37c18324dcba45ea7a2c72750eedd5463d98c956435a69181190db168bb1b4。",
